        } else {
            // Office floors
            // Office desks - 4 private offices along back wall
            var officeXs = [-7.5, -2.5, 2.5, 7.5];
            var officeNames = ["A", "B", "C", "D"];
            for (var oi = 0; oi < 4; oi++) {
                var ox = officeXs[oi];
                var on2 = officeNames[oi];
                // Interior walls between offices
                if (oi < 3) {
